function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw center circle
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // draw connected circles
  for (let i = 0; i < 10; i++) {
    let radius = 20 + 10 * Math.sin(t + i);
    let x = W/2 + 100 * Math.cos(t + i);
    let y = H/2 + 100 * Math.sin(t + i);
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, 2 * Math.PI);
    ctx.stroke();

    // draw lines connecting circles
    ctx.beginPath();
    ctx.moveTo(W/2, H/2);
    ctx.lineTo(x, y);
    ctx.stroke();
  }

  // draw stick figures around center
  for (let i = 0; i < 5; i++) {
    let x = W/2 + 150 * Math.cos(t + i * 2);
    let y = H/2 + 150 * Math.sin(t + i * 2);
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 10);
    ctx.lineTo(x, y + 50);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 30);
    ctx.lineTo(x - 20, y + 50);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 30);
    ctx.lineTo(x + 20, y + 50);
    ctx.stroke();
  }

  ctx.restore();
}
